## `ringbuf.c`

```c
#include "ringbuf.h"

/* 2の累乗用マスク（例: 256 → 0xFF） */
#define MASK  (RINGBUF_CAPACITY - 1u)

void ringbuf_init(ringbuf_t *rb)
{
    atomic_store(&rb->write_idx, 0);
    atomic_store(&rb->read_idx, 0);
    for (uint32_t i = 0; i < RINGBUF_CAPACITY; ++i) {
        rb->data[i] = 0;
    }
}

/* ------------------------------------------------------------------ */
/*  プロデューサ（例: 割り込みハンドラ）                               */
/* ------------------------------------------------------------------ */
int ringbuf_push(ringbuf_t *rb, uint8_t val)
{
    uint32_t w = atomic_load_explicit(&rb->write_idx, memory_order_relaxed);
    uint32_t r = atomic_load_explicit(&rb->read_idx, memory_order_acquire);

    /* 満杯チェック */
    if (w - r == RINGBUF_CAPACITY) {
        return -1;
    }

    /* データを書き込む */
    rb->data[w & MASK] = val;

    /* インデックス更新（Release: 上のデータ書き込みが先に可視化される） */
    atomic_store_explicit(&rb->write_idx, w + 1, memory_order_release);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  コンシューマ（例: メインループ）                                   */
/* ------------------------------------------------------------------ */
int ringbuf_pop(ringbuf_t *rb, uint8_t *out)
{
    uint32_t r = atomic_load_explicit(&rb->read_idx, memory_order_relaxed);
    uint32_t w = atomic_load_explicit(&rb->write_idx, memory_order_acquire);

    /* 空チェック */
    if (r == w) {
        return -1;
    }

    /* データを読み出す */
    *out = rb->data[r & MASK];

    /* インデックス更新（Release: 読み出しが完了してから更新） */
    atomic_store_explicit(&rb->read_idx, r + 1, memory_order_release);
    return 0;
}

uint32_t ringbuf_count(const ringbuf_t *rb)
{
    /* 読み取り専用なので relaxed で十分（厳密には race-free） */
    return atomic_load(&rb->write_idx) - atomic_load(&rb->read_idx);
}
```

