## `main.c`（使用例）

```c
#include <stdio.h>
#include <stdint.h>
#include "ringbuf.h"

/*
 * 例: 32-bit MCU 相当を想定。
 *   - 割り込みハンドラ（プロデューサ）が ADC 値を push
 *   - メインループ（コンシューマ）が pop して UART 送信
 *
 * ここではデモとして、両方メインループで呼ぶ。
 */

void demo(void)
{
    static ringbuf_t rb;
    ringbuf_init(&rb);

    /* --- 生産者：10 個 push --- */
    for (uint8_t i = 0; i < 10; ++i) {
        if (ringbuf_push(&rb, i * 10) != 0) {
            printf("overflow!\n");
            return;
        }
    }
    printf("pushed 10 items, count = %u\n", ringbuf_count(&rb));

    /* --- コンシューマ：pop して UART に送る想定 --- */
    uint8_t val;
    while (ringbuf_pop(&rb, &val) == 0) {
        printf("  pop -> %u\n", val);
    }

    /* 空になった */
    printf("buffer empty, count = %u\n", ringbuf_count(&rb));
}

int main(void)
{
    /* 1回だけデモ */
    demo();

    /* 実際の割り込み環境では:
     *
     *   void ADC_IRQHandler(void) {
     *       uint8_t adc_val = ADC->DR;       // ハードウェア読み出し
     *       ringbuf_push(&rb, adc_val);    // 割り込みセーフな push
     *   }
     *
     *   int main(void) {
     *       ringbuf_init(&rb);
     *       ADC_enable();
     *       while (1) {
     *           uint8_t v;
     *           if (ringbuf_pop(&rb, &v) == 0)
     *               UART_send(v);
     *           else
     *               WFI();               // WFE/WFI で待機
     *       }
     *   }
     */
    return 0;
}
```

